import{t as e}from"./jsx-runtime-lw2jiZar.js";import{t}from"./activity-BFe0pMCz.js";import{C as n,E as r,M as i,N as a,O as o,P as s,S as c,b as l,k as u,l as d,n as f,o as p,p as m,t as h,u as g}from"./shared-DP9JVsk0.js";import{t as _}from"./database-LLH4Psoh.js";import{t as v}from"./refresh-cw-4z12SyhZ.js";import{O as y}from"./index-DLaUeCZy.js";var b=e(),x=`Этап 4 · Блок 16 · Надёжность и приёмка Planner`;function S({module:e}){return(0,b.jsxs)(a,{children:[(0,b.jsx)(i,{variant:`project`,chip:e??x,title:`79. Сквозная проверка`,intro:`Свяжем API, CLI и новое чтение из SQLite в одной приёмочной истории, сохраняя уже работающие договоры Planner.`,tags:[{icon:(0,b.jsx)(t,{size:14}),label:`одна история`},{icon:(0,b.jsx)(_,{size:14}),label:`общая SQLite`},{icon:(0,b.jsx)(v,{size:14}),label:`новый процесс`},{icon:(0,b.jsx)(y,{size:14}),label:`без fallback`}]}),(0,b.jsxs)(s,{number:`00`,title:`От отдельных проверок к одной истории`,children:[(0,b.jsx)(o,{children:`Мы уже проверяли отдельные операции Planner: запись задачи, изменение, запрос и обработку отказа. Теперь проверим, сходятся ли эти результаты в обычном продукте. Одна задача пройдёт через HTTP API и CLI, останется в той же базе после нового запуска и сохранит прежние правила ответа.`}),(0,b.jsx)(u,{variant:`connected`,items:[{title:`Точка старта`,description:`Один SQL-путь, прежние API/CLI-возможности и отдельная тестовая база. Результаты предыдущих занятий подтверждаем по журналу и checkpoint, а не по номеру урока.`},{title:`Новый вопрос`,description:`Видят ли оба интерфейса одно сохранённое состояние после своих коротких Session и после перезапуска?`},{title:`Результат`,description:`Собираем проверенную историю продукта, сохраняем прежний договор и записываем только реально полученные результаты.`}]}),(0,b.jsx)(`p`,{children:`Приёмка не повторяет реализацию CRUD и не создаёт новый учебный Planner. Мы выбираем один безопасный сценарий и смотрим, как меняется сохранённая задача на каждом переходе. Перед работой сверяем фактический checkpoint: если записи или кода для занятий 76–78 нет, их результаты не считаем освоенными и не выдаём зависимые проверки за пройденные. Независимую часть всё равно можно выполнить на подтверждённой точке A.`})]}),(0,b.jsxs)(s,{number:`01`,title:`Каждый вид проверки доказывает своё`,children:[(0,b.jsx)(o,{children:`Unit-тест подтверждает правило небольшой функции. HTTP-тест проверяет маршрут, статус и форму ответа. Сквозная проверка соединяет уже готовые части и показывает, что они работают вместе через настоящую точку входа.`}),(0,b.jsx)(`p`,{children:`Представим эстафету. На каждом участке можно проверить скорость одного бегуна, но финишная запись зависит ещё и от передачи палочки. В приложении отдельными участками будут API, сервис, репозиторий, CLI и SQLite. Сквозной сценарий проверяет передачу состояния между ними. Граница аналогии проста: задача не движется как предмет между процессами, а читается из одного сохранённого источника после завершения предыдущей операции.`}),(0,b.jsx)(`p`,{children:`Успешный POST полезен: он подтверждает создание и ответ конкретного маршрута. Но он сам по себе не показывает, что CLI использует тот же адрес базы, что последующее изменение сохранилось или что другая Session прочитает его. Для этих выводов нужны новые наблюдения, которые проверяют разные границы. Мы заранее формулируем утверждение и подбираем свидетельство именно для него.`}),(0,b.jsx)(l,{question:`После ответа 201 от API мы уже доказали, что CLI найдёт эту задачу в общей базе?`,options:[`Да, статус 201 подтверждает оба интерфейса`,`Нет, CLI нужно отдельно запустить с тем же адресом и найти тот же id`,`Да, если ответ содержит поле id`],correctIndex:1,explanation:`Мы подтвердили создание через HTTP. Общий адрес и чтение CLI пока остаются отдельными утверждениями, которые нужно проверить.`}),(0,b.jsx)(`p`,{children:`Сценарий остаётся небольшим: создать временную задачу, найти её через другой интерфейс, изменить, прочитать снова и сопоставить результат с ожидаемым договором. Автоматические тесты расширяют число случаев, а ручной проход помогает увидеть, где именно приложение использует другой процесс, другой адрес или старое состояние.`})]}),(0,b.jsxs)(s,{number:`02`,title:`Начинаем с изолированной базы и обычной сборки`,children:[(0,b.jsx)(o,{children:`Проверка должна быть безопасной для рабочих задач и одновременно проходить через тот способ запуска, которым пользуется продукт. Поэтому сначала выбираем отдельный SQLite-файл и один DATABASE_URL для API и CLI.`}),(0,b.jsx)(`p`,{children:`Изоляция означает, что пробные добавления и удаления не затронут рабочие строки. Для ручного сценария это отдельный временный файл базы; для автоматического SQL-теста это обычно файл внутри tmp_path. Мы создаём исходную схему явной командой, если она нужна тесту. Обработчик запроса не должен молча создавать таблицы, переключать backend или стирать строки ради удобства проверки.`}),(0,b.jsx)(`p`,{children:`Проверим, откуда каждый обычный процесс получает адрес. Если тест вручную подменяет provider или app.state, он полезен для узкой проверки поведения, но уже не доказывает корректность штатной конфигурации. В приёмке API и CLI запускаются с одним и тем же DATABASE_URL; внутри каждой команды создаётся своя короткая Session. Мы не передаём одну живую Session от HTTP-сервера к терминалу.`}),(0,b.jsx)(`p`,{children:`Похожая бытовая картина: два сотрудника пользуются одним журналом склада, но каждый берёт его на время своей операции и закрывает после работы. Общий журнал сохраняет состояние, короткое использование ресурса ограничивает время владения. Аналогия не описывает транзакции буквально: целостность изменения по-прежнему задают правила базы и транзакционная граница приложения.`}),(0,b.jsx)(`p`,{children:`Схема ниже показывает порядок проверки, а не устройство всех внутренних функций. Два узла SQLite подписаны одинаково: это один файл по DATABASE_URL, а не копии. Новый запрос использует новую Session, CLI выполняет отдельную команду, а следующий запуск исключает память прежнего процесса.`}),(0,b.jsxs)(h,{caption:`Одна задача проходит через обычные интерфейсы`,orientation:`vertical`,children:[(0,b.jsxs)(p,{label:`Сохранённая задача между API, CLI и новым запуском`,orientation:`vertical`,children:[(0,b.jsx)(d,{title:`API: создать задачу`,shape:`process`,children:(0,b.jsx)(`p`,{children:`Запрос проходит штатный provider и сервис`})}),(0,b.jsx)(f,{label:`commit завершён`}),(0,b.jsx)(d,{title:`SQLite по DATABASE_URL`,shape:`database`,children:(0,b.jsx)(`p`,{children:`Сохранены id и состояние задачи`})}),(0,b.jsx)(f,{label:`новый ресурс CLI читает тот же путь`}),(0,b.jsx)(d,{title:`CLI: найти и изменить`,shape:`process`,children:(0,b.jsx)(`p`,{children:`Своя команда и короткая Session`})}),(0,b.jsx)(f,{label:`остановить и снова запустить API`}),(0,b.jsx)(d,{title:`SQLite по DATABASE_URL`,shape:`database`,children:(0,b.jsx)(`p`,{children:`Тот же файл после смены процесса`})}),(0,b.jsx)(f,{label:`новая Session читает результат`}),(0,b.jsx)(d,{title:`API: получить задачу и статистику`,shape:`process`,children:(0,b.jsx)(`p`,{children:`Ответ согласован с изменением CLI`})})]}),(0,b.jsx)(g,{title:`Как читать схему`,children:(0,b.jsx)(`p`,{children:`Повторный узел базы обозначает тот же адрес хранения. Перезапуск меняет процесс и его память, но не должен менять выбранный файл.`})})]}),(0,b.jsx)(m,{prompt:`Сопоставим наблюдение с тем, что оно подтверждает.`,leftTitle:`Наблюдение`,rightTitle:`Подтверждаем`,pairs:[{left:(0,b.jsx)(`code`,{children:`POST 201`}),right:`API создал задачу и вернул id`},{left:(0,b.jsx)(`code`,{children:`CLI find того же id`}),right:`CLI прочитал запись по своему ресурсу`},{left:(0,b.jsx)(`code`,{children:`API GET после CLI done`}),right:`Изменение видно через API`},{left:(0,b.jsx)(`code`,{children:`GET после перезапуска`}),right:`Результат не зависит от старого процесса`}],explanation:`Мы соединяем каждое утверждение только с тем наблюдением, которое действительно его подтверждает.`}),(0,b.jsx)(`p`,{children:`Если тест подменяет глобальный provider или окружение, после него нужно восстановить исходное состояние. Если запускаем отдельные процессы, передаём им одинаковые настройки явно. Временная база должна быть доступна обоим процессам по одному файловому адресу; SQLite :memory: не подходит для этой истории, потому что отдельные соединения могут увидеть разные базы.`})]}),(0,b.jsxs)(s,{number:`03`,title:`Защищаем прежний договор, а не только happy path`,children:[(0,b.jsx)(o,{children:`После связанного чтения проверяем, что операции по-прежнему означают то же самое. Статус ответа, состояние строки и дальнейшее чтение связаны, но это разные свидетельства.`}),(0,b.jsx)(`p`,{children:`Мы используем созданные в тестовой базе задачи, чтобы пройти PUT, PATCH и удаление без риска для рабочих данных. Полная замена сохраняет id и внутренние tags. Частичное обновление применяет переданное False и игнорирует отсутствующие поля и явный null. Пустой объект оставляет состояние прежним; вывод об отсутствии лишней SQL-записи требует наблюдателя из занятия 77 и принимается только при подтверждённом checkpoint. Фильтр применяется до порядка и limit, статистика считает исходный набор, а не случайную страницу.`}),(0,b.jsx)(`p`,{children:`Для удаления сначала проверим ответ 204 без тела, затем новым GET подтвердим 404. Ответ 204 означает, что маршрут сообщил об успешном удалении; отдельное чтение подтверждает, что записи больше нет. Также проверяем соседа и внутренние поля через разрешённый SQL/CLI путь: публичная схема может намеренно не возвращать tags и технический title_normalized.`}),(0,b.jsx)(c,{statement:`Если DELETE вернул 204, отдельный GET уже ничего не добавит к доказательству удаления.`,isTrue:!1,explanation:`Мы проверяем два разных результата: ответ маршрута и отсутствие записи при последующем чтении. GET 404 подтверждает состояние после операции.`}),(0,b.jsx)(`p`,{children:`Сохраняем исходные формы маршрутов и ошибок. Невалидное тело или limit остаётся 422, отсутствующий id остаётся 404, а пустой список после фильтра не становится ошибкой. Мы не добавляем новый HTTP endpoint для поиска, не раскрываем служебные поля и не превращаем тестовый запрос в новую возможность Planner.`})]}),(0,b.jsxs)(s,{number:`04`,title:`Известный отказ проверяем отдельно и безопасно`,children:[(0,b.jsx)(o,{children:`Связный успешный путь не заменяет отказной, но и отказ не должен повредить приёмочную базу или скрыться под видом пустого результата.`}),(0,b.jsx)(`p`,{children:`Сначала различаем причину. Отсутствующая задача относится к прежнему 404, недопустимый ввод к 422, заранее распознанная недоступность хранилища может дать безопасный 503 и понятный отказ CLI. Неожиданное внутреннее нарушение нельзя назвать пустым списком или успешной операцией. Путь и параметры SQL, секреты и пользовательские данные не попадают в клиентское сообщение.`}),(0,b.jsx)(`p`,{children:`Для направленного отказа используем уже подготовленную проверку из занятий 76–76.1 на отдельной временной базе. Не удаляем рабочий файл, не блокируем реальную таблицу и не ловим исключение шире, чем нужно. После отказа возвращаем корректный тестовый адрес и выполняем новую независимую операцию. Так мы наблюдаем и безопасный отказ, и восстановление.`}),(0,b.jsx)(`p`,{children:`В отладочной карточке ниже показан короткий фрагмент на границе списка, а исправление показывает только обработчик для уже существующего FastAPI-маршрута. Мы не выдаём его за целый модуль или готовую новую ручку.`}),(0,b.jsx)(n,{code:`def list_tasks(planner):
    try:
        return planner.list_tasks()
    except Exception:
        return []`,question:`Что не так с этим обработчиком, если база стала недоступна?`,options:[`Любое исключение превращается в HTTP 200 с пустым списком и скрывает причину отказа`,`Пустой список обязательно закрывает Session и тем самым чинит подключение`,`Такой обработчик сохраняет прежний 404 для неизвестного id`],correctIndex:0,explanation:`Мы не должны маскировать ошибку хранения как успешную выдачу. Известную StorageError обрабатываем на предусмотренной границе безопасным отказом, а неожиданное исключение не превращаем в фиктивное состояние.`,fix:`except StorageError as error:
    raise HTTPException(status_code=503, detail="Database unavailable") from error`}),(0,b.jsx)(`p`,{children:`Граница commit тоже важна. Ошибка до подтверждения операции допускает rollback и проверку отсутствия частичной записи. Если commit уже завершился, последующее исключение не отменяет сохранённую задачу. Поэтому мы не запускаем POST заново автоматически и не восстанавливаем строки из устаревшего снимка JSON.`})]}),(0,b.jsxs)(s,{number:`05`,title:`Новый процесс отделяет данные от старой памяти`,children:[(0,b.jsx)(o,{children:`Когда изменения видны в запросах одного запуска, закрываем API и CLI, затем запускаем их снова с теми же настройками. Это проверяет сохранённое состояние после исчезновения старого процесса.`}),(0,b.jsx)(`p`,{children:`Внутри Session SQLAlchemy ведёт identity map: если мы снова попросим уже загруженную строку тем же ключом в той же Session, ORM может вернуть известный объект. Это нормальная оптимизация в пределах ресурса, а не доказательство долговременного чтения. Новая Session отделяет результат от прежней identity map; новый процесс дополнительно исключает случайную зависимость от переменной или объекта старого приложения.`}),(0,b.jsx)(`p`,{children:`Это похоже на заметку, которую один дежурный передал следующей смене через общий журнал. Если следующий человек видит только записку на экране прошлого сотрудника, общий журнал ещё не проверен. Для приложения SQLite-файл играет роль долговременной записи, а новая Session и новый запуск дают независимый путь чтения. Аналогия не означает, что Session является файлом или что перезапуск сам по себе проверяет все правила приложения.`}),(0,b.jsx)(`p`,{children:`После запуска сверяем id, title, is_done, статистику и внутренние tags допустимым способом. Проверяем, что задача, созданная через API, находится через CLI, а изменение через CLI видно в API. Старый JSON-backend не должен читаться или создаваться как запасной источник. Отдельный импортёр может остаться, но в этой штатной истории он не запускается.`}),(0,b.jsx)(l,{question:`Почему новое чтение после перезапуска сильнее чтения в той же Session?`,options:[`Новая Session получает другую identity map, а новый процесс убирает старые объекты и переменные из проверки`,`При каждом запуске SQLite автоматически очищает таблицу и создаёт новую`,`Перезапуск доказывает, что README и чистая установка воспроизводимы`],correctIndex:0,explanation:`Мы проверяем долговременный источник независимым ресурсом. Полная воспроизводимость чистого checkout относится к следующей передаче и требует отдельной проверки.`})]}),(0,b.jsxs)(s,{number:`06`,title:`Health и preferences остаются в своих границах`,children:[(0,b.jsx)(o,{children:`Финальная история включает прежние endpoints и настройки представления, но не приписывает им новую семантику.`}),(0,b.jsx)(`p`,{children:`Health проверяем по его текущему контракту: например, прежний ответ приложения 200 с состоянием ok. Такой ответ не обязательно проверяет каждую таблицу или подтверждает, что все записи можно прочитать. Мы не расширяем endpoint ради этого занятия без причины в плане.`}),(0,b.jsx)(`p`,{children:`Preferences проверяем как настройки вида интерфейса и заголовков клиента. Cookie planner_view хранит compact или detailed, но не удостоверяет пользователя и не защищает задачи. TestClient запускаем без автоматического follow_redirects, когда нужно увидеть точный статус и заголовки исходного ответа. Клиентскую тему и health не используем как замену приёмке SQLite.`}),(0,b.jsx)(r,{tone:`info`,children:`Каждое наблюдение поддерживает конкретный вывод: health говорит о прежней доступности приложения, preferences о настройке представления, новая Session о чтении из базы. Не объединяем их в обещание авторизации или production-готовности.`}),(0,b.jsx)(`p`,{children:`Итоговая запись должна отделять запущенные проверки от тех, которые мы не выполняли. Если 76–78 ещё не подтверждены журналом и checkpoint, соответствующую часть отказа и query-проверки отмечаем как непринимаемую, а не как успешную. Полный чистый checkout с установкой зависимостей остаётся задачей следующего занятия.`})]}),(0,b.jsxs)(s,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,b.jsx)(o,{children:`Мы пройдём сохранённую историю в существующем Planner на отдельной SQLite-базе и будем привязывать каждый вывод к конкретному наблюдению.`}),(0,b.jsx)(u,{variant:`connected`,items:[{title:`Подготовим границу`,description:`Сверим фактический checkpoint, выберем тестовый файл и подтвердим один DATABASE_URL для обычных API и CLI запусков.`},{title:`Свяжем интерфейсы`,description:`Создадим временную задачу через API, найдём и изменим её CLI, затем прочитаем id и статистику новым API запросом.`},{title:`Проверим договор`,description:`Сверим PUT, PATCH, фильтр, порядок, limit и удаление с независимым чтением, включая внутренние поля и соседа.`},{title:`Повторим после запуска`,description:`Остановим процессы, откроем их снова с прежним адресом и проверим сохранённое состояние новой Session.`},{title:`Примем отказ и результат`,description:`Раздельно сверим checkpoint: отказ и восстановление 76–76.1, безопасное SQL-наблюдение 77, запрос 78. Отсутствующую опору отметим как непроверенную.`}]}),(0,b.jsx)(`p`,{children:`Порядок идёт от безопасной конфигурации к нормальной истории, затем к повторному чтению и отдельной проверке отказа. В результате останутся id задачи, ответы API, вывод CLI после перезапуска, статистика и точные статусы тестов. Если checkpoint части 76–78 отсутствует, записываем её как пропущенную, не как принятую. Если мы нашли дефект, исправляем только связанный участок и повторяем затронутую проверку; уже работающий продукт не переписываем. После практики следующий шаг сможет проверить тот же результат на чистой копии по README.`})]})]})}export{S as Lesson79};